const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Polygon([
    [[-6.0, 50.0], [-6.0, 53.5], [2.0, 53.5], [2.0, 50.0]]
  ]);

  const date = '2024-01-02';

  // 2. Data Acquisition
  const precipCollection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(region)
    .select('precipitation');

  const collectionSize = precipCollection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get daily precipitation sum
  const dailyPrecip = precipCollection.sum();

  // Check for valid pixels
  const pixelCount = dailyPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Check if any pixels have >=35mm precipitation
  const thresholdMask = dailyPrecip.gte(35);

  const thresholdCount = thresholdMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const maxPrecip = dailyPrecip.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Max precipitation: ${maxPrecip?.toFixed(2)} mm`);
  console.log(`Pixels with >=35mm: ${thresholdCount}`);

  // 5. Validation & Final Answer
  if (maxPrecip === null || maxPrecip === undefined || isNaN(maxPrecip)) {
    console.log("<answer>C3</answer>");
  } else if (thresholdCount > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
